/* @lc app=leetcode id=3510 lang=kotlin */ class Solution { fun minimumPairRemoval(nums: IntArray): Int = nums.size.let { n -> LongArray(n) { nums[it].toLong() }.let { v -> IntArray(n) { it - 1 }.let { pv -> IntArray(n) { if (it < n - 1) it + 1 else -1 }.let { nx -> BooleanArray(n) { true }.let { alive -> java.util.PriorityQueue<LongArray>(compareBy<LongArray>({ it[0] }, { it[1] })).let { pq -> (0 until n - 1).forEach { pq.add(longArrayOf(v[it] + v[it + 1], it.toLong(), (it + 1).toLong())) }.let { (0 until n - 1).count { v[it] > v[it + 1] }.let { bad0 -> generateSequence(bad0) { bad -> if (bad == 0) null else generateSequence { pq.poll() }.first { e -> alive[e[1].toInt()] && nx[e[1].toInt()] == e[2].toInt() && v[e[1].toInt()] + v[e[2].toInt()] == e[0] }.let { e -> e[1].toInt().let { i -> e[2].toInt().let { j -> pv[i].let { l -> nx[j].let { r -> (bad - (if (l >= 0 && v[l] > v[i]) 1 else 0) - (if (v[i] > v[j]) 1 else 0) - (if (r >= 0 && v[j] > v[r]) 1 else 0)).let { b2 -> v.set(i, e[0]).also { alive[j] = false }.also { nx[i] = r }.also { if (r >= 0) pv[r] = i }.also { if (l >= 0) pq.add(longArrayOf(v[l] + v[i], l.toLong(), i.toLong())) }.also { if (r >= 0) pq.add(longArrayOf(v[i] + v[r], i.toLong(), r.toLong())) }.let { b2 + (if (l >= 0 && v[l] > v[i]) 1 else 0) + (if (r >= 0 && v[i] > v[r]) 1 else 0) } } } } } } } }.count() - 1 } } } } } } } } }